// AUTO-GENERATED by Claude Code
// Purpose: keys of a "/assign" proposal in the chat (ui.assign_item, assign.py): Escape in
//          its code box drops it (as its Drop button does). Enter running it is the box's own
//          (it submits the form); Shift+Enter is a new line.
(() => {
  // capture phase: before the page's Escape (panes.js), which would close something else
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape" || !(event.target instanceof Element)) return;
    if (!event.target.matches("[data-assign-code]")) return;
    const drop = event.target.form && event.target.form.querySelector("[data-assign-drop]");
    if (!drop) return;
    event.preventDefault();
    event.stopPropagation();
    drop.click();
    // back to the chat box, where the command was typed
    const box = document.querySelector('textarea[name="prompt"]');
    if (box) box.focus();
  }, true);
})();
